To connect to multiple hosts via SSH and keep the connections alive, you can use the Paramiko library in Python. Here's a script that demonstrates how to do this:
```python
import paramiko
import time

# Replace these with your actual ssh credentials
SSH_USER = "username"
SSH_PASS = "password"

# Add the hosts you want to connect to, with their respective SSH keys if needed
HOSTS = {
    "host1": ["username1@host1", "~/.ssh/id_rsa_host1"],
    "host2": ["username2@host2", "~/.ssh/id_rsa_host2"],
    "host3": ["username3@host3", "~/.ssh/id_rsa_host3"]
}

# Function to check if a connection is still alive
def is_connection_alive(ssh_client):
    # You can tailor this method to better suit your needs
    try:
        ssh_client.exec_command("ping -c 1 -W 1 8.8.8.8")
        return True
    except Exception as e:
        return False

# Function to send a command to all hosts
def send_command(command, ssh_clients):
    for hostname, ssh_client in ssh_clients.items():
        if is_connection_alive(ssh_client):
            try:
                stdin, stdout, stderr = ssh_client.exec_command(command)
                output = stdout.read().decode('utf-8')
                print(f"{hostname} : {output}")
            except Exception as e:
                print(f"{hostname} : Error - {e}")

# Initialize the SSH clients
ssh_clients = {}
for host, credentials in HOSTS.items():
    # You can use pexpect or other libraries for better error handling
    ssh_client = paramiko.SSHClient()
    ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())

    for cred in credentials:
        if isinstance(cred, str):
            ssh_client.connect(host, username=cred, password=SSH_PASS)
        else:
            key_file = cred[0]
            with open(key_file, 'r') as f:
                private_key = f.read()

            ssh_client.connect(host, username=cred[1], pkey=paramiko.RSAKey(private_key))

    ssh_clients[host] = ssh_client

# Keep the connections alive by sending a command every 10 minutes
while True:
    time.sleep(600)  # 10 minutes
    send_command("uptime", ssh_clients)
```
This script connects to the specified hosts using SSH and keeps the connections alive by sending an `uptime` command every 10 minutes. You can replace the `send_command` function with your own command(s) to execute on the connected hosts.

Please note that this script does not handle exceptions that may occur during the SSH connection process (e.g., password prompts, key pair mismatches, etc.). You may want to use a library like `pexpect` for more robust error handling.

