import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;

import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

public class WordPuzzle {

    public static void main(String[] args) throws Exception {
        Path filePath = Paths.get("words.xml");
        List<String> words = new ArrayList<>();

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document document = builder.parse(Files.newInputStream(filePath));

        Element root = document.getDocumentElement();
        NodeList wordNodes = root.getElementsByTagName("word");
        for (int i = 0; i < wordNodes.getLength(); i++) {
            words.add(wordNodes.item(i).getTextContent());
        }

        String puzzle = "lap";
        List<String> possibleWords = findPossibleWords(words, puzzle);
        System.out.println("Possible words that match the puzzle " + puzzle + ": " + possibleWords);
    }

    private static List<String> findPossibleWords(List<String> words, String puzzle) {
        List<String> possibleWords = new ArrayList<>();
        for (String word : words) {
            if (word.startsWith(puzzle)) {
                possibleWords.add(word);
            }
        }
        return possibleWords;
    }
}
